+              return descriptions[stripFileInfoPrefix(cl)];\n\
+          }\n\
+\n\
+          if (descriptions[stripInfoPrefix(cl)] !== undefined) {\n\
+              return descriptions[stripInfoPrefix(cl)];\n\
+          }\n\
+\n\
+          if (descriptions[stripBinPrefix(cl)] !== undefined) {\n\
+              return descriptions[stripBinPrefix(cl)];\n\
+          }\n\
+\n\
+          return null;\n\
+      }\n\
+\n\
+      function iterateParents(el) {\n\
+          let txt = \"\";\n\
+          let keywords = [];\n\
+\n\
+          do {\n\
+              let classList = el.classList;\n\
+              if (classList !== undefined) {\n\
+                  for (let i = 0; i < classList.length; ++i) {\n\
+                      keywords.push(classList[i]);\n\
+                  }\n\
+              }\n\
+\n\
+              el = el.parentNode;\n\
+          } while (el !== null && el.tagName !== \"HTML\")\n\
+\n\
+          // fix all occurences where segments and sections overlap.\n\
+          // once again we are relying on programming by which sections are always inside segments.\n\
+          // also, this is O(n^2) ugly.\n\
+          let i = 1;\n\
+          while (i < keywords.length) {\n\
+              if (keywords[i] !== 'segment') {\n\
+                  ++i;\n\
+                  continue;\n\
+              }\n\
+\n\
+              let have_section_before = false;\n\
+              let j = 0;\n\
+              for (; j < i; ++j) {\n\
+                  if (keywords[j] == 'section') {\n\
+                      have_section_before = true;\n\
+                      break;\n\
+                  }\n\
+              }\n\
+\n\
+              if (have_section_before) {\n\
+                  keywords[i] = 'section_in_segment';\n\
+                  keywords.splice(j, 1);\n\
+              } else {\n\
+                  ++i;\n\
+              }\n\
+          }\n\
+\n\
+          for (let i = 0; i < keywords.length; ++i) {\n\
+              let keyword = keywords[i];\n\
+              let desc = getDesc(keyword);\n\
+\n\
+              if (desc !== null) {\n\
+                  if (txt === \"\") {\n\
+                      txt = desc;\n\
+                  } else {\n\
+                      txt = desc + separator + txt;\n\
+                  }\n\
+              }\n\
+          }\n\
+\n\
+          return txt;\n\
+      }\n\
+\n\
+      document.addEventListener(\"mouseover\", function (e) {\n\
+          let event = e || window.event;\n\
+\n\
+          let target = event.target || event.srcElement;\n\
+\n\
+          if (!target.classList.contains('legend_rect')) {\n\
+              document.getElementById('desc').innerHTML = iterateParents(target);\n\
+          }\n\
+      }, false);\n\
+    </script>\n\
+    <script type='text/javascript'>\n\
+      let prevShownTables = [];\n\
+\n\
+      function getFirstClass(el) {\n\
+          let cls = el.classList[0];\n\
+\n\
+          if (cls === undefined) {\n\
+              return \"\";\n\
+          } else {\n\
+              return cls;\n\
+          }\n\
+      }\n\
+\n\
+      function listOfParents(el) {\n\
+          let list = [getFirstClass(el)];\n\
+\n\
+          while (el.tagName !== \"HTML\") {\n\
+              el = el.parentNode;\n\
+\n\
+              list.unshift(getFirstClass(el));\n\
+          }\n\
+\n\
+          return list;\n\
+      }\n\
+\n\
+      function hidePreviousTables() {\n\
+          for (let i = 0; i < prevShownTables.length; ++i) {\n\
+              prevShownTables[i].style.display = \"none\";\n\
+              prevShownTables[i].classList.remove(\"indirect\");\n\
+          }\n\
+      }\n\
+\n\
+      function showIfMatches(cl, prefix, newPrefix, indirect = false) {\n\
+          if (!cl.startsWith(prefix)) {\n\
+              return;\n\
+          }\n\
+\n\
+          let tableId = cl.replace(prefix, newPrefix);\n\
+          let table = document.getElementById(tableId);\n\
+\n\
+          if (table === null) {\n\
+              return;\n\
+          }\n\
+\n\
+          table.style.display = \"block\";\n\
+\n\
+          if (indirect) {\n\
+              table.classList.add(\"indirect\");\n\
+          } else {\n\
+              table.classList.remove(\"indirect\");\n\
+          }\n\
+\n\
+          prevShownTables.push(table);\n\
+      }\n\
+\n\
+      document.addEventListener(\"mouseover\", function (e) {\n\
+          let event = e || window.event;\n\
+          let target = event.target || event.srcElement;\n\
+          let parents = listOfParents(target);\n\
+          let cleared = false;\n\
+          const prefix = 'bin_';\n\
+\n\
+          for (let i = 0; i < parents.length; i++) {\n\
+              let cl = parents[i];\n\
+\n\
+              if (!cl.startsWith(prefix)) {\n\
+                  continue;\n\
+              }\n\
+\n\
+              if (!cleared) {\n\
+                  cleared = true;\n\
+                  hidePreviousTables();\n\
+              }\n\
+\n\
+              showIfMatches(cl, prefix, \"info_\");\n\
+              showIfMatches(cl, \"bin_segment\", \"info_phdr\", true);\n\
+              showIfMatches(cl, \"bin_section\", \"info_shdr\", true);\n\
+          }\n\
+      }, false);\n\
+    </script>\n\
+    <script type='text/javascript'>\n\
+      let fileLen = ",
+    );
+    let _ = writeln!(out, "{}", elf.data.len());
+    out.push_str(
+        "      function populateOffsets(columns) {\n\
+          let rows = Math.ceil(fileLen / columns);\n\
+          let elements = \"\";\n\
+          let offset = 0;\n\
+\n\
+          for (let i = 0; i < rows; ++i) {\n\
+              elements += offset.toString(16) + \"</br>\\n\";\n\
+              offset += columns;\n\
+          }\n\
+\n\
+          document.getElementById('offsets').innerHTML = elements;\n\
+      }\n\
+    </script>\n\
+    <script type='text/javascript'>\n\
+      const arrows = document.getElementById('arrows');\n\
+      let connections = [];\n\
+      let batchElems = '';\n\
+\n\
+      function getAbsPosition(elem) {\n\
+          let x = 0, y = 0;\n\
+\n\
+          do {\n\
+              x += elem.offsetLeft || 0;\n\
+              y += elem.offsetTop || 0;\n\
+\n\
+              elem = elem.offsetParent;\n\
+          } while (elem);\n\
+\n\
+          return {\n\
+              x: x,\n\
+              y: y\n\
+          };\n\
+      }\n\
+\n\
+      function getBoundingBoxSizes(elem) {\n\
+          let rect = elem.getBoundingClientRect();\n\
+\n\
+          return {\n\
+              w: rect.width || elem.offsetWidth,\n\
+              h: rect.height || elem.offsetHeight\n\
