+          let bb1 = getBoundingBoxSizes(elem1);\n\
+\n\
+          let x1 = off1.x + bb1.w / 2;\n\
+          let y1 = off1.y;\n\
+\n\
+          let x2 = off2.x;\n\
+          let y2 = off2.y;\n\
+\n\
+          batchElems += '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" '\n\
+                            + 'x2=\"' + x2 + '\" y2=\"' + y2 + '\"/>';\n\
+      }\n\
+\n\
+      function jumpToElem(elem) {\n\
+          elem.scrollIntoView();\n\
+      }\n\
+\n\
+      function setJumpCallback(elemFrom, elemTo) {\n\
+          elemFrom.addEventListener(\"click\", function(e) {\n\
+              jumpToElem(elemTo);\n\
+          }, true);\n\
+      }\n\
+\n\
+      function connect(sel1, sel2) {\n\
+          let elem1 = document.querySelector(sel1);\n\
+          let elem2 = document.querySelector(sel2);\n\
+\n\
+          if (elem1 === null || elem2 === null) {\n\
+              return;\n\
+          }\n\
+\n\
+          connections.push([elem1, elem2]);\n\
+\n\
+          addSvgArrow(elem1, elem2);\n\
+\n\
+          setJumpCallback(elem1, elem2);\n\
+          setJumpCallback(elem2, elem1);\n\
+      }\n\
+\n\
+      function clearArrows() {\n\
+          batchElems = '';\n\
+\n\
+          arrows.innerHTML = '';\n\
+      }\n\
+\n\
+      function pushArrowElems() {\n\
+          arrows.innerHTML = batchElems;\n\
+      }\n\
+\n\
+      function redrawArrows() {\n\
+          clearArrows();\n\
+\n\
+          for (let i = 0; i < connections.length; ++i) {\n\
+              let conn = connections[i];\n\
+\n\
+              addSvgArrow(conn[0], conn[1]);\n\
+          }\n\
+\n\
+          pushArrowElems();\n\
+      }\n\
+\n\
+      window.onresize = function() {\n\
+          redrawArrows();\n\
+      }\n",
+    );
+
+    push_connections(&mut out, elf);
+
+    out.push_str(
+        "      pushArrowElems();\n\
+    </script>\n\
+    <script type='text/javascript'>\n\
+      const settings = document.getElementById('settings');\n\
+      const help = document.getElementById('help');\n\
+      const arrow_input = document.getElementById('arrow_opacity_range');\n\
+      /* const arrows is reused from arrows.js */\n\
+\n\
+      function toggleVisibility(elem) {\n\
+          if (elem.style.display === \"none\" || elem.style.display === \"\") {\n\
+              elem.style.display = \"block\";\n\
+          } else {\n\
+              elem.style.display = \"none\";\n\
+          }\n\
+      }\n\
+\n\
+      document.getElementById('settings_toggle').onclick = function() {\n\
+          toggleVisibility(settings);\n\
+\n\
+          help.style.display = \"none\";\n\
+      }\n\
+\n\
+      document.getElementById('help_toggle').onclick = function() {\n\
+          toggleVisibility(help);\n\
+\n\
+          settings.style.display = \"none\";\n\
+      }\n\
+\n\
+      function setArrowOpacity(e) {\n\
+          arrows.style.opacity = e.target.valueAsNumber / 100;\n\
+      }\n\
+\n\
+      arrow_input.addEventListener('change', setArrowOpacity);\n\
+      arrow_input.addEventListener('input', setArrowOpacity);\n\
+    </script>\n\
+  </body>\n\
+</html>\n",
+    );
+
+    out
+}
