+fn push_file_info(out: &mut String, elf: &ElfFile, input_path: &str) {
+    let header = &elf.header;
+    let _ = writeln!(
+        out,
+        "      <tr class='fileinfo_file_name'> <td>File name:</td> <td>{}</td> </tr>",
+        input_path
+    );
+    let _ = writeln!(
+        out,
+        "      <tr class='fileinfo_file_size'> <td>File size:</td> <td>{}</td> </tr>",
+        format_top_size(elf.data.len() as u64)
+    );
+    let _ = writeln!(
+        out,
+        "      <tr class='fileinfo_class'> <td>Object class:</td> <td>{}</td> </tr>",
+        match elf.class {
+            Class::Elf32 => "32-bit",
+            Class::Elf64 => "64-bit",
+        }
+    );
+    let _ = writeln!(
+        out,
+        "      <tr class='fileinfo_data'> <td>Data encoding:</td> <td>{}</td> </tr>",
+        match elf.endian {
+            crate::elf::Endian::Little => "Little endian",
+            crate::elf::Endian::Big => "Big endian",
+        }
+    );
+
+    let abi = abi_name(header.ident[7]);
+    if header.ident[7] == ELFOSABI_SYSV && header.ident[8] == 0 {
+        let _ = writeln!(
+            out,
+            "      <tr class='fileinfo_abi'> <td>ABI:</td> <td>{}</td> </tr>",
+            abi
+        );
+    } else {
+        let _ = writeln!(
+            out,
+            "      <tr class='fileinfo_abi'> <td>Uncommon ABI(!):</td> <td>{}</td> </tr>",
+            abi
+        );
+        let _ = writeln!(
+            out,
+            "      <tr class='fileinfo_abi_ver'> <td>ABI version:</td> <td>{}</td> </tr>",
+            header.ident[8]
+        );
+    }
+
+    let _ = writeln!(
+        out,
+        "      <tr class='fileinfo_e_type'> <td>Type:</td> <td>{}</td> </tr>",
+        etype_name(header.e_type)
+    );
+    let _ = writeln!(
+        out,
+        "      <tr class='fileinfo_e_machine'> <td>Architecture:</td> <td>{}</td> </tr>",
+        machine_name(header.e_machine)
+    );
+    let _ = writeln!(
+        out,
+        "      <tr class='fileinfo_e_entry'> <td>Entrypoint:</td> <td>{}</td> </tr>",
+        num_hex_dec_title(header.e_entry)
+    );
+    let _ = writeln!(
+        out,
+        "      <tr class='fileinfo_ph'> <td>Program headers:</td> <td>{} * {} @ {}</td> </tr>",
+        num_dec_hex_title_class(u64::from(header.e_phnum), "fileinfo_e_phnum"),
+        num_dec_hex_title_class(u64::from(header.e_phentsize), "fileinfo_e_phentsize"),
+        num_dec_hex_title_class(header.e_phoff, "fileinfo_e_phoff"),
+    );
+    let _ = writeln!(
+        out,
+        "      <tr class='fileinfo_sh'> <td>Section headers:</td> <td>{} * {} @ {}</td> </tr>",
+        num_dec_hex_title_class(u64::from(header.e_shnum), "fileinfo_e_shnum"),
+        num_dec_hex_title_class(u64::from(header.e_shentsize), "fileinfo_e_shentsize"),
+        num_dec_hex_title_class(header.e_shoff, "fileinfo_e_shoff"),
+    );
+}
+
+fn push_offsets(out: &mut String, len: usize) {
+    let rows = len.div_ceil(16);
+    for row in 0..rows {
+        if row != 0 {
+            out.push('\n');
+        }
+        let _ = write!(out, "{:x}", row * 16);
+    }
+}
+
+fn push_ascii(out: &mut String, data: &[u8]) {
+    for (idx, byte) in data.iter().enumerate() {
+        if idx != 0 && idx % 16 == 0 {
+            out.push('\n');
+        }
+        push_ascii_char(out, *byte);
+    }
+}
+
+fn push_ascii_char(out: &mut String, byte: u8) {
+    if !(0x20..=0x7e).contains(&byte) {
+        out.push('.');
+        return;
+    }
+
+    match byte {
+        b'&' => out.push_str("&amp;"),
+        b'<' => out.push_str("&lt;"),
+        b'>' => out.push_str("&gt;"),
+        b'\'' => out.push_str("&apos;"),
+        b'"' => out.push_str("&quot;"),
+        other => out.push(char::from(other)),
+    }
+}
+
+fn push_bytes(out: &mut String, elf: &ElfFile) {
+    let regions = collect_regions(elf);
+    let mut region_idx = 0usize;
+    let mut stack: Vec<&Region> = Vec::new();
+
+    for idx in 0..elf.data.len() {
+        while region_idx < regions.len() && regions[region_idx].start == idx {
+            out.push_str(&regions[region_idx].open);
+            stack.push(&regions[region_idx]);
+            region_idx += 1;
+        }
+
+        push_byte_token(out, idx, elf.data[idx]);
+
+        while stack.last().is_some_and(|region| region.end == idx + 1) {
+            out.push_str("</span>");
+            stack.pop();
+        }
+
+        if idx + 1 < elf.data.len() {
+            if (idx + 1) % 16 == 0 {
+                out.push('\n');
+            } else {
+                out.push(' ');
+            }
+        }
+    }
+}
+
+fn push_byte_token(out: &mut String, idx: usize, byte: u8) {
+    if (1..=3).contains(&idx) {
+        out.push_str("&nbsp;");
+        out.push(char::from(byte));
+    } else {
+        let _ = write!(out, "{byte:02x}");
+    }
+}
+
+fn collect_regions(elf: &ElfFile) -> Vec<Region> {
+    let mut order = 0usize;
+    let len = elf.data.len();
+    let mut regions = Vec::new();
+    let header = &elf.header;
+
+    let ehdr_size = elf.class.header_size();
+    add_region(
+        &mut regions,
+        0,
+        ehdr_size,
+        "ehdr",
+        30,
+        &mut order,
+        len,
+    );
+    add_region(&mut regions, 0, 16, "ident", 31, &mut order, len);
+    add_region(&mut regions, 0, 4, "magic", 32, &mut order, len);
+    add_region(&mut regions, 4, 5, "class", 32, &mut order, len);
+    add_region(&mut regions, 5, 6, "data", 32, &mut order, len);
+    add_region(&mut regions, 6, 7, "ver", 32, &mut order, len);
+    add_region(&mut regions, 7, 8, "abi", 32, &mut order, len);
+    add_region(&mut regions, 8, 9, "abi_ver", 32, &mut order, len);
+    add_region(&mut regions, 9, 16, "pad", 32, &mut order, len);
+
+    match elf.class {
+        Class::Elf32 => {
+            add_region(&mut regions, 16, 18, "e_type", 32, &mut order, len);
+            add_region(&mut regions, 18, 20, "e_machine", 32, &mut order, len);
+            add_region(&mut regions, 20, 24, "e_version", 32, &mut order, len);
+            add_region(&mut regions, 24, 28, "e_entry", 32, &mut order, len);
+            add_region(&mut regions, 28, 32, "e_phoff", 32, &mut order, len);
+            add_region(&mut regions, 32, 36, "e_shoff", 32, &mut order, len);
+            add_region(&mut regions, 36, 40, "e_flags", 32, &mut order, len);
+            add_region(&mut regions, 40, 42, "e_ehsize", 32, &mut order, len);
+            add_region(&mut regions, 42, 44, "e_phentsize", 32, &mut order, len);
+            add_region(&mut regions, 44, 46, "e_phnum", 32, &mut order, len);
+            add_region(&mut regions, 46, 48, "e_shentsize", 32, &mut order, len);
+            add_region(&mut regions, 48, 50, "e_shnum", 32, &mut order, len);
+            add_region(&mut regions, 50, 52, "e_shstrndx", 32, &mut order, len);
+        }
+        Class::Elf64 => {
+            add_region(&mut regions, 16, 18, "e_type", 32, &mut order, len);
+            add_region(&mut regions, 18, 20, "e_machine", 32, &mut order, len);
+            add_region(&mut regions, 20, 24, "e_version", 32, &mut order, len);
+            add_region(&mut regions, 24, 32, "e_entry", 32, &mut order, len);
+            add_region(&mut regions, 32, 40, "e_phoff", 32, &mut order, len);
+            add_region(&mut regions, 40, 48, "e_shoff", 32, &mut order, len);
+            add_region(&mut regions, 48, 52, "e_flags", 32, &mut order, len);
+            add_region(&mut regions, 52, 54, "e_ehsize", 32, &mut order, len);
+            add_region(&mut regions, 54, 56, "e_phentsize", 32, &mut order, len);
+            add_region(&mut regions, 56, 58, "e_phnum", 32, &mut order, len);
+            add_region(&mut regions, 58, 60, "e_shentsize", 32, &mut order, len);
+            add_region(&mut regions, 60, 62, "e_shnum", 32, &mut order, len);
+            add_region(&mut regions, 62, 64, "e_shstrndx", 32, &mut order, len);
+        }
+    }
+
+    for phdr in &elf.program_headers {
+        let start = usize::try_from(header.e_phoff).unwrap() + phdr.index * usize::from(header.e_phentsize);
+        let end = start + usize::from(header.e_phentsize);
+        add_region(
+            &mut regions,
+            start,
+            end,
+            &format!("bin_phdr{} phdr", phdr.index),
+            20,
+            &mut order,
+            len,
+        );
+
+        match elf.class {
+            Class::Elf32 => {
+                add_region(&mut regions, start, start + 4, "p_type", 32, &mut order, len);
+                add_region(&mut regions, start + 4, start + 8, "p_offset", 32, &mut order, len);
+                add_region(&mut regions, start + 8, start + 12, "p_vaddr", 32, &mut order, len);
+                add_region(&mut regions, start + 12, start + 16, "p_paddr", 32, &mut order, len);
+                add_region(&mut regions, start + 16, start + 20, "p_filesz", 32, &mut order, len);
+                add_region(&mut regions, start + 20, start + 24, "p_memsz", 32, &mut order, len);
+                add_region(&mut regions, start + 24, start + 28, "p_flags", 32, &mut order, len);
+                add_region(&mut regions, start + 28, start + 32, "p_align", 32, &mut order, len);
+            }
+            Class::Elf64 => {
+                add_region(&mut regions, start, start + 4, "p_type", 32, &mut order, len);
+                add_region(&mut regions, start + 4, start + 8, "p_flags", 32, &mut order, len);
+                add_region(&mut regions, start + 8, start + 16, "p_offset", 32, &mut order, len);
+                add_region(&mut regions, start + 16, start + 24, "p_vaddr", 32, &mut order, len);
+                add_region(&mut regions, start + 24, start + 32, "p_paddr", 32, &mut order, len);
+                add_region(&mut regions, start + 32, start + 40, "p_filesz", 32, &mut order, len);
+                add_region(&mut regions, start + 40, start + 48, "p_memsz", 32, &mut order, len);
+                add_region(&mut regions, start + 48, start + 56, "p_align", 32, &mut order, len);
+            }
+        }
+    }
+
+    for shdr in &elf.section_headers {
+        let start = usize::try_from(header.e_shoff).unwrap() + shdr.index * usize::from(header.e_shentsize);
+        let end = start + usize::from(header.e_shentsize);
+        add_region(
+            &mut regions,
+            start,
+            end,
+            &format!("bin_shdr{} shdr", shdr.index),
+            20,
+            &mut order,
+            len,
+        );
+
+        match elf.class {
+            Class::Elf32 => {
+                add_region(&mut regions, start, start + 4, "sh_name", 32, &mut order, len);
+                add_region(&mut regions, start + 4, start + 8, "sh_type", 32, &mut order, len);
+                add_region(&mut regions, start + 8, start + 12, "sh_flags", 32, &mut order, len);
+                add_region(&mut regions, start + 12, start + 16, "sh_addr", 32, &mut order, len);
+                add_region(&mut regions, start + 16, start + 20, "sh_offset", 32, &mut order, len);
+                add_region(&mut regions, start + 20, start + 24, "sh_size", 32, &mut order, len);
+                add_region(&mut regions, start + 24, start + 28, "sh_link", 32, &mut order, len);
+                add_region(&mut regions, start + 28, start + 32, "sh_info", 32, &mut order, len);
+                add_region(&mut regions, start + 32, start + 36, "sh_addralign", 32, &mut order, len);
+                add_region(&mut regions, start + 36, start + 40, "sh_entsize", 32, &mut order, len);
+            }
+            Class::Elf64 => {
+                add_region(&mut regions, start, start + 4, "sh_name", 32, &mut order, len);
+                add_region(&mut regions, start + 4, start + 8, "sh_type", 32, &mut order, len);
+                add_region(&mut regions, start + 8, start + 16, "sh_flags", 32, &mut order, len);
+                add_region(&mut regions, start + 16, start + 24, "sh_addr", 32, &mut order, len);
+                add_region(&mut regions, start + 24, start + 32, "sh_offset", 32, &mut order, len);
+                add_region(&mut regions, start + 32, start + 40, "sh_size", 32, &mut order, len);
+                add_region(&mut regions, start + 40, start + 44, "sh_link", 32, &mut order, len);
+                add_region(&mut regions, start + 44, start + 48, "sh_info", 32, &mut order, len);
+                add_region(&mut regions, start + 48, start + 56, "sh_addralign", 32, &mut order, len);
+                add_region(&mut regions, start + 56, start + 64, "sh_entsize", 32, &mut order, len);
+            }
+        }
+    }
+
+    let rendered_segment_indexes = elf.rendered_segment_indexes();
+    for phdr in elf
+        .program_headers
+        .iter()
+        .filter(|phdr| rendered_segment_indexes.contains(&phdr.index))
+    {
+        let start = usize::try_from(phdr.p_offset).unwrap();
+        let end = start + usize::try_from(phdr.p_filesz).unwrap();
+        add_region(
+            &mut regions,
+            start,
+            end,
+            &format!("bin_segment{} segment", phdr.index),
+            0,
+            &mut order,
+            len,
+        );
+    }
+
+    for shdr in &elf.section_headers {
+        if shdr.sh_type == SHT_NOBITS || shdr.sh_size == 0 {
+            continue;
+        }
+        let start = usize::try_from(shdr.sh_offset).unwrap();
+        let end = start + usize::try_from(shdr.sh_size).unwrap();
+        add_region(
+            &mut regions,
+            start,
+            end,
+            &format!("bin_section{} section hover", shdr.index),
+            1,
+            &mut order,
+            len,
+        );
+
+        if shdr.sh_type == SHT_NOTE
+            && elf
+                .program_headers
+                .iter()
+                .any(|phdr| phdr.p_type == PT_NOTE && phdr.p_offset != 0 && phdr.p_filesz != 0
+                    && usize::try_from(phdr.p_offset).unwrap() <= start
+                    && usize::try_from(phdr.p_offset + phdr.p_filesz).unwrap() >= end)
+        {
+            add_region(
+                &mut regions,
+                start,
+                end,
+                "segment_subrange hover",
+                2,
+                &mut order,
+                len,
+            );
+        }
+    }
+
+    regions.sort_by(|a, b| {
+        a.start
+            .cmp(&b.start)
+            .then_with(|| b.end.cmp(&a.end))
+            .then_with(|| a.priority.cmp(&b.priority))
+            .then_with(|| a.order.cmp(&b.order))
+    });
+    regions
+}
+
+fn add_region(
+    regions: &mut Vec<Region>,
+    start: usize,
+    end: usize,
+    class: &str,
+    priority: u8,
+    order: &mut usize,
+    len: usize,
+) {
+    if start >= end {
+        return;
+    }
+    assert!(end <= len);
+    regions.push(Region {
+        start,
+        end,
+        open: format!("<span class='{class}'>"),
+        priority,
+        order: *order,
+    });
+    *order += 1;
+}
