+fn format_size_field(value: u64) -> String {
+    if value < 1024 {
+        return value.to_string();
+    }
+    format!("{value} ({})", human_size(value))
+}
+
+fn format_top_size(value: u64) -> String {
+    if value < 1024 {
+        return format!("{value} B");
+    }
+    format!("{} ({value} B)", human_size(value))
+}
+
+fn human_size(mut value: u64) -> String {
+    let units = ["KiB", "MiB", "GiB", "TiB"];
+    let mut unit = 0usize;
+    let mut scaled = value as f64 / 1024.0;
+    while scaled >= 1024.0 && unit + 1 < units.len() {
+        value /= 1024;
+        scaled = value as f64 / 1024.0;
+        unit += 1;
+    }
+    format!("{scaled:.1} {}", units[unit])
+}
