use std::fmt;

const EI_NIDENT: usize = 16;
const ELF32_EHDR_SIZE: usize = 52;
const ELF64_EHDR_SIZE: usize = 64;
const ELF32_PHDR_SIZE: usize = 32;
const ELF64_PHDR_SIZE: usize = 56;
const ELF32_SHDR_SIZE: usize = 40;
const ELF64_SHDR_SIZE: usize = 64;

pub const ELFOSABI_SYSV: u8 = 0;
pub const PT_INTERP: u32 = 3;
pub const PT_NOTE: u32 = 4;
pub const PT_GNU_EH_FRAME: u32 = 0x6474_e550;
pub const PT_GNU_STACK: u32 = 0x6474_e551;
pub const PT_GNU_RELRO: u32 = 0x6474_e552;
pub const SHT_STRTAB: u32 = 3;
pub const SHT_NOBITS: u32 = 8;
pub const SHT_NOTE: u32 = 7;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Class {
    Elf32,
    Elf64,
}

impl Class {
    pub fn header_size(self) -> usize {
        match self {
            Self::Elf32 => ELF32_EHDR_SIZE,
            Self::Elf64 => ELF64_EHDR_SIZE,
        }
    }

    pub fn phdr_size(self) -> usize {
        match self {
            Self::Elf32 => ELF32_PHDR_SIZE,
            Self::Elf64 => ELF64_PHDR_SIZE,
        }
    }

    pub fn shdr_size(self) -> usize {
        match self {
            Self::Elf32 => ELF32_SHDR_SIZE,
            Self::Elf64 => ELF64_SHDR_SIZE,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Endian {
    Little,
    Big,
}

#[derive(Debug)]
pub struct ParseError(pub String);

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

#[derive(Clone, Debug)]
pub struct ElfHeader {
    pub ident: [u8; EI_NIDENT],
    pub e_type: u16,
    pub e_machine: u16,
    pub e_version: u32,
    pub e_entry: u64,
    pub e_phoff: u64,
    pub e_shoff: u64,
    pub e_flags: u32,
    pub e_ehsize: u16,
    pub e_phentsize: u16,
    pub e_phnum: u16,
    pub e_shentsize: u16,
    pub e_shnum: u16,
    pub e_shstrndx: u16,
}

#[derive(Clone, Debug)]
pub struct ProgramHeader {
    pub index: usize,
    pub p_type: u32,
    pub p_flags: u32,
    pub p_offset: u64,
    pub p_vaddr: u64,
    pub p_paddr: u64,
    pub p_filesz: u64,
    pub p_memsz: u64,
    pub p_align: u64,
}

#[derive(Clone, Debug)]
pub struct SectionHeader {
    pub index: usize,
    pub sh_name: u32,
    pub sh_type: u32,
    pub sh_flags: u64,
    pub sh_addr: u64,
    pub sh_offset: u64,
    pub sh_size: u64,
    pub sh_link: u32,
    pub sh_info: u32,
    pub sh_addralign: u64,
    pub sh_entsize: u64,
    pub name: String,
}

#[derive(Clone, Debug)]
pub struct Note {
    pub name: String,
    pub note_type: u32,
    pub desc: Vec<u8>,
}

#[derive(Clone, Debug)]
pub struct ElfFile {
    pub class: Class,
    pub endian: Endian,
    pub header: ElfHeader,
    pub program_headers: Vec<ProgramHeader>,
    pub section_headers: Vec<SectionHeader>,
    pub data: Vec<u8>,
}

impl ElfFile {
    pub fn parse(data: Vec<u8>) -> Result<Self, ParseError> {
        if data.len() < EI_NIDENT {
            return Err(ParseError(
                "file is smaller than ELF header's e_ident".to_string(),
            ));
        }

        if data[0] != 0x7f || data[1] != b'E' || data[2] != b'L' || data[3] != b'F' {
            return Err(ParseError("mismatched magic: not an ELF file".to_string()));
        }

        let class = match data[4] {
            1 => Class::Elf32,
            2 => Class::Elf64,
            other => return Err(ParseError(format!("Unknown bitness: {other}"))),
        };

        let endian = match data[5] {
            1 => Endian::Little,
            2 => Endian::Big,
            other => return Err(ParseError(format!("Unknown endianness: {other}"))),
        };

        if data.len() < class.header_size() {
            return Err(ParseError("file is smaller than ELF file header".to_string()));
        }

        let ident: [u8; EI_NIDENT] = data[..EI_NIDENT].try_into().unwrap();
        let header = parse_header(&data, class, endian, ident);
        let program_headers = parse_program_headers(&data, class, endian, &header);
        let mut section_headers = parse_section_headers(&data, class, endian, &header);
        assign_section_names(&data, &header, &mut section_headers);

        Ok(Self {
            class,
            endian,
            header,
            program_headers,
            section_headers,
            data,
        })
    }

    pub fn section_data(&self, shdr: &SectionHeader) -> Option<&[u8]> {
        if shdr.sh_type == SHT_NOBITS || shdr.sh_size == 0 {
            return None;
        }
        let start = usize::try_from(shdr.sh_offset).unwrap();
        let end = start + usize::try_from(shdr.sh_size).unwrap();
        Some(&self.data[start..end])
    }

    pub fn program_data(&self, phdr: &ProgramHeader) -> Option<&[u8]> {
        if phdr.p_filesz == 0 {
            return None;
        }
        let start = usize::try_from(phdr.p_offset).unwrap();
        let end = start + usize::try_from(phdr.p_filesz).unwrap();
        Some(&self.data[start..end])
    }

    pub fn rendered_segment_indexes(&self) -> Vec<usize> {
        self.program_headers
            .iter()
            .filter(|phdr| phdr.p_offset != 0 && phdr.p_filesz != 0)
            .map(|phdr| phdr.index)
            .collect()
    }

    pub fn parse_segment_notes(&self, phdr: &ProgramHeader) -> Vec<Note> {
        if phdr.p_type != PT_NOTE {
            return Vec::new();
        }
        let Some(bytes) = self.program_data(phdr) else {
            return Vec::new();
        };

        let mut notes = Vec::new();
        let mut offset = 0usize;
        while offset + 12 <= bytes.len() {
            let namesz = read_u32(bytes, self.endian, offset) as usize;
            let descsz = read_u32(bytes, self.endian, offset + 4) as usize;
            let note_type = read_u32(bytes, self.endian, offset + 8);
            offset += 12;

            if offset + namesz > bytes.len() {
                break;
            }
            let name_raw = &bytes[offset..offset + namesz];
            offset += align4(namesz);

            if offset + descsz > bytes.len() {
                break;
            }
            let desc = bytes[offset..offset + descsz].to_vec();
            offset += align4(descsz);

            let mut name = name_raw;
            if let Some(stripped) = name.strip_suffix(&[0]) {
                name = stripped;
            }

            notes.push(Note {
                name: String::from_utf8_lossy(name).into_owned(),
                note_type,
                desc,
            });
        }

        notes
    }

    pub fn interpreter(&self, phdr: &ProgramHeader) -> Option<String> {
        if phdr.p_type != PT_INTERP {
            return None;
        }
        let bytes = self.program_data(phdr)?;
        let bytes = bytes.strip_suffix(&[0]).unwrap_or(bytes);
        Some(String::from_utf8_lossy(bytes).into_owned())
    }

    pub fn string_table_entries(&self, shdr: &SectionHeader) -> Vec<String> {
        if shdr.sh_type != SHT_STRTAB {
            return Vec::new();
        }
        let Some(bytes) = self.section_data(shdr) else {
            return Vec::new();
        };
        bytes
            .split(|byte| *byte == 0)
            .filter(|entry| !entry.is_empty())
            .map(|entry| String::from_utf8_lossy(entry).into_owned())
            .collect()
    }
}

fn parse_header(data: &[u8], class: Class, endian: Endian, ident: [u8; EI_NIDENT]) -> ElfHeader {
    match class {
        Class::Elf32 => ElfHeader {
            ident,
            e_type: read_u16(data, endian, 16),
            e_machine: read_u16(data, endian, 18),
            e_version: read_u32(data, endian, 20),
            e_entry: u64::from(read_u32(data, endian, 24)),
            e_phoff: u64::from(read_u32(data, endian, 28)),
            e_shoff: u64::from(read_u32(data, endian, 32)),
            e_flags: read_u32(data, endian, 36),
            e_ehsize: read_u16(data, endian, 40),
            e_phentsize: read_u16(data, endian, 42),
            e_phnum: read_u16(data, endian, 44),
            e_shentsize: read_u16(data, endian, 46),
            e_shnum: read_u16(data, endian, 48),
            e_shstrndx: read_u16(data, endian, 50),
        },
        Class::Elf64 => ElfHeader {
            ident,
            e_type: read_u16(data, endian, 16),
            e_machine: read_u16(data, endian, 18),
            e_version: read_u32(data, endian, 20),
            e_entry: read_u64(data, endian, 24),
            e_phoff: read_u64(data, endian, 32),
            e_shoff: read_u64(data, endian, 40),
            e_flags: read_u32(data, endian, 48),
            e_ehsize: read_u16(data, endian, 52),
            e_phentsize: read_u16(data, endian, 54),
            e_phnum: read_u16(data, endian, 56),
            e_shentsize: read_u16(data, endian, 58),
            e_shnum: read_u16(data, endian, 60),
            e_shstrndx: read_u16(data, endian, 62),
        },
    }
}

fn parse_program_headers(
    data: &[u8],
    class: Class,
    endian: Endian,
    header: &ElfHeader,
) -> Vec<ProgramHeader> {
    let mut headers = Vec::with_capacity(usize::from(header.e_phnum));
    let phoff = usize::try_from(header.e_phoff).unwrap();
    let entsize = usize::from(header.e_phentsize);

    for index in 0..usize::from(header.e_phnum) {
        let base = phoff + index * entsize;
        let phdr = match class {
            Class::Elf32 => ProgramHeader {
                index,
                p_type: read_u32(data, endian, base),
                p_flags: read_u32(data, endian, base + 24),
                p_offset: u64::from(read_u32(data, endian, base + 4)),
                p_vaddr: u64::from(read_u32(data, endian, base + 8)),
                p_paddr: u64::from(read_u32(data, endian, base + 12)),
                p_filesz: u64::from(read_u32(data, endian, base + 16)),
                p_memsz: u64::from(read_u32(data, endian, base + 20)),
                p_align: u64::from(read_u32(data, endian, base + 28)),
            },
            Class::Elf64 => ProgramHeader {
                index,
                p_type: read_u32(data, endian, base),
                p_flags: read_u32(data, endian, base + 4),
                p_offset: read_u64(data, endian, base + 8),
                p_vaddr: read_u64(data, endian, base + 16),
                p_paddr: read_u64(data, endian, base + 24),
                p_filesz: read_u64(data, endian, base + 32),
                p_memsz: read_u64(data, endian, base + 40),
                p_align: read_u64(data, endian, base + 48),
            },
        };
        headers.push(phdr);
    }

    headers
}

fn parse_section_headers(
    data: &[u8],
    class: Class,
    endian: Endian,
    header: &ElfHeader,
) -> Vec<SectionHeader> {
    let mut headers = Vec::with_capacity(usize::from(header.e_shnum));
    let shoff = usize::try_from(header.e_shoff).unwrap();
    let entsize = usize::from(header.e_shentsize);

    for index in 0..usize::from(header.e_shnum) {
        let base = shoff + index * entsize;
        let shdr = match class {
            Class::Elf32 => SectionHeader {
                index,
                sh_name: read_u32(data, endian, base),
                sh_type: read_u32(data, endian, base + 4),
                sh_flags: u64::from(read_u32(data, endian, base + 8)),
                sh_addr: u64::from(read_u32(data, endian, base + 12)),
                sh_offset: u64::from(read_u32(data, endian, base + 16)),
                sh_size: u64::from(read_u32(data, endian, base + 20)),
                sh_link: read_u32(data, endian, base + 24),
                sh_info: read_u32(data, endian, base + 28),
                sh_addralign: u64::from(read_u32(data, endian, base + 32)),
                sh_entsize: u64::from(read_u32(data, endian, base + 36)),
                name: String::new(),
            },
            Class::Elf64 => SectionHeader {
                index,
                sh_name: read_u32(data, endian, base),
                sh_type: read_u32(data, endian, base + 4),
                sh_flags: read_u64(data, endian, base + 8),
                sh_addr: read_u64(data, endian, base + 16),
                sh_offset: read_u64(data, endian, base + 24),
                sh_size: read_u64(data, endian, base + 32),
                sh_link: read_u32(data, endian, base + 40),
                sh_info: read_u32(data, endian, base + 44),
                sh_addralign: read_u64(data, endian, base + 48),
                sh_entsize: read_u64(data, endian, base + 56),
                name: String::new(),
            },
        };
        headers.push(shdr);
    }

    headers
}

fn assign_section_names(data: &[u8], header: &ElfHeader, section_headers: &mut [SectionHeader]) {
    if section_headers.is_empty() {
        return;
    }

    let shstrndx = usize::from(header.e_shstrndx);
    if shstrndx >= section_headers.len() {
        return;
    }

    let shstr = &section_headers[shstrndx];
    let start = usize::try_from(shstr.sh_offset).unwrap();
    let end = start + usize::try_from(shstr.sh_size).unwrap();
    let table = &data[start..end];

    for shdr in section_headers {
        let offset = usize::try_from(shdr.sh_name).unwrap();
        let tail = &table[offset..];
        let len = tail.iter().position(|byte| *byte == 0).unwrap_or(tail.len());
        shdr.name = String::from_utf8_lossy(&tail[..len]).into_owned();
    }
}

fn align4(value: usize) -> usize {
    (value + 3) & !3
}

fn read_u16(data: &[u8], endian: Endian, offset: usize) -> u16 {
    let bytes: [u8; 2] = data[offset..offset + 2].try_into().unwrap();
    match endian {
        Endian::Little => u16::from_le_bytes(bytes),
        Endian::Big => u16::from_be_bytes(bytes),
    }
}

fn read_u32(data: &[u8], endian: Endian, offset: usize) -> u32 {
    let bytes: [u8; 4] = data[offset..offset + 4].try_into().unwrap();
    match endian {
        Endian::Little => u32::from_le_bytes(bytes),
        Endian::Big => u32::from_be_bytes(bytes),
    }
}

fn read_u64(data: &[u8], endian: Endian, offset: usize) -> u64 {
    let bytes: [u8; 8] = data[offset..offset + 8].try_into().unwrap();
    match endian {
        Endian::Little => u64::from_le_bytes(bytes),
        Endian::Big => u64::from_be_bytes(bytes),
    }
}

