mod elf;
mod render;

use std::ffi::OsStr;
use std::fs;
use std::path::Path;
use std::process;

use elf::ElfFile;

fn print_usage() {
    println!("Usage: elfcat <filename>");
    println!("Writes <filename>.html to CWD.");
}

fn output_name(path: &str) -> String {
    let base = Path::new(path)
        .file_name()
        .unwrap_or_else(|| OsStr::new(path))
        .to_string_lossy();
    format!("{base}.html")
}

fn run(path: &str) -> Result<(), i32> {
    let data = match fs::read(path) {
        Ok(data) => data,
        Err(err) => {
            eprintln!("Failed to read file {:?}: {}", path, err);
            return Err(1);
        }
    };

    let elf = match ElfFile::parse(data) {
        Ok(elf) => elf,
        Err(err) => {
            eprintln!("Failed to parse ELF: {}", err);
            return Err(1);
        }
    };

    let html = render::render_html(&elf, path);
    let output = output_name(path);
    if let Err(err) = fs::write(output, html) {
        eprintln!("Failed to write report: {}", err);
        return Err(1);
    }

    Ok(())
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    match args.as_slice() {
        [_, flag] if flag == "-h" || flag == "--help" => {
            print_usage();
        }
        [_, flag] if flag == "--version" => {
            println!("elfcat 0.1.10");
        }
        [_, path] => {
            if let Err(code) = run(path) {
                process::exit(code);
            }
        }
        _ => {
            print_usage();
            process::exit(1);
        }
    }
}

