fn push_file_info(out: &mut String, elf: &ElfFile, input_path: &str) {
    let header = &elf.header;
    let _ = writeln!(
        out,
        "      <tr class='fileinfo_file_name'> <td>File name:</td> <td>{}</td> </tr>",
        input_path
    );
    let _ = writeln!(
        out,
        "      <tr class='fileinfo_file_size'> <td>File size:</td> <td>{}</td> </tr>",
        format_top_size(elf.data.len() as u64)
    );
    let _ = writeln!(
        out,
        "      <tr class='fileinfo_class'> <td>Object class:</td> <td>{}</td> </tr>",
        match elf.class {
            Class::Elf32 => "32-bit",
            Class::Elf64 => "64-bit",
        }
    );
    let _ = writeln!(
        out,
        "      <tr class='fileinfo_data'> <td>Data encoding:</td> <td>{}</td> </tr>",
        match elf.endian {
            crate::elf::Endian::Little => "Little endian",
            crate::elf::Endian::Big => "Big endian",
        }
    );

    let abi = abi_name(header.ident[7]);
